-- =============================================================================
-- MIGRACIÓN DE DATOS LOCALES (SQLite → Supabase)
-- Generado desde dicor.db local
-- Incluye: 29 remitos, 436 remito_items válidos, 293 historial_precios
-- Los items huérfanos (de remitos eliminados) fueron descartados.
-- Las rutas PDF locales se reemplazan por NULL (no aplican en la web).
-- =============================================================================

BEGIN;

-- =============================================================================
-- 1. REMITOS (29 registros)
-- =============================================================================

ON CONFLICT (id) DO NOTHING;

-- Actualizar la secuencia para que los próximos remitos no colisionen
SELECT setval('remitos_id_seq', (SELECT MAX(id) FROM remitos));

-- =============================================================================
-- 2. REMITO_ITEMS (436 registros válidos — items huérfanos descartados)
-- =============================================================================

ON CONFLICT (id) DO NOTHING;

-- Total items insertados: 436
SELECT setval('remito_items_id_seq', (SELECT MAX(id) FROM remito_items));

-- =============================================================================
-- 3. HISTORIAL_PRECIOS (293 registros)
-- =============================================================================

ON CONFLICT (id) DO NOTHING;

-- Total historial insertado: 293
SELECT setval('historial_precios_id_seq', (SELECT MAX(id) FROM historial_precios));

COMMIT;
